// The caller supplies bytes, never a remote URL. PDF JavaScript/eval is disabled.
export function pdfDocumentOptions(bytes,assetBase,password){return {data:bytes,cMapUrl:assetBase+'cmaps/',cMapPacked:true,standardFontDataUrl:assetBase+'standard_fonts/',wasmUrl:assetBase+'wasm/',isEvalSupported:false,useWasm:false,enableXfa:false,maxImageSize:32000000,canvasMaxAreaInBytes:16000000,useSystemFonts:true,...(password?{password}:{})};}
export function fitPdfViewport(page,width,dpr=1,zoom=1){const base=page.getViewport({scale:1});if(!Number.isFinite(base.width)||!Number.isFinite(base.height)||base.width<=0||base.height<=0)throw Error('PDF 页尺寸无效。');const scale=Math.min(900,Math.max(120,width))/base.width*Math.min(3,Math.max(0.5,Number(zoom)||1));const viewport=page.getViewport({scale});const ratio=Math.min(2,Math.max(1,Number(dpr)||1),Math.sqrt(4000000/(viewport.width*viewport.height)));return {viewport,width:Math.max(1,Math.floor(viewport.width*ratio)),height:Math.max(1,Math.floor(viewport.height*ratio)),transform:ratio===1?undefined:[ratio,0,0,ratio,0,0]};}
